<template><div class="dash-stack"><div class="dash-toolbar"><div><h2>{{isCreate?'New land record':'Update land record'}}</h2><p>Area is assigned by the server. Save a draft or send the complete record to final.</p></div><IconButton icon="cancel" label="Cancel" @click="$router.back()"/></div><div v-if="hasDraft" class="draft-in-progress draft-form-indicator">Draft in progress <span v-if="isStale">· Stale — publishing will be blocked</span><IconButton icon="delete" label="Discard draft" variant="danger" @click="discardOpen=true"/></div><form class="glass-panel land-form" @submit.prevent="publish"><p v-if="!isCreate" class="record-label">{{draftId}}</p><section class="land-form-section"><h3>01 · Parcel</h3><div class="form-grid"><label>Record type<select v-model="form.recordType" required><option value="RS">RS</option><option value="BS">BS</option></select></label><label>Dag number<input v-model="form.dagNo" required maxlength="40"/></label><label>JL number<input v-model="form.jlNo" maxlength="40"/></label><label>Khatian number<input v-model="form.khatianNo" maxlength="40"/></label><label>Area (decimal)<input v-model.number="form.areaDecimal" type="number" min="0" step="0.01"/></label><label>Land class<select v-model="form.landClass"><option value="">Select land class</option><option v-for="value in VALUE_SETS.land_class" :key="value" :value="value">{{value}}</option></select></label></div></section>
<section class="land-form-section"><h3>02 · Documents</h3><div class="form-grid"><label>Khatian reference<input v-model="form.khatianRef"/></label><label>Khatian status<select v-model="form.khatianStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.khatian_status" :key="v" :value="v">{{v}}</option></select></label><label>Deed number<input v-model="form.deedNo"/></label><label>Deed date<input v-model="form.deedDate" type="date"/></label><label>Registration office<input v-model="form.deedRegistrationOffice"/></label><label>Mutation reference<input v-model="form.mutationRef"/></label><label>Mutation status<select v-model="form.mutationStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.mutation_status" :key="v" :value="v">{{v}}</option></select></label><label>DCR reference<input v-model="form.dcrRef"/></label><label>DCR status<select v-model="form.dcrStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.dcr_status" :key="v" :value="v">{{v}}</option></select></label><label>Dakhila reference<input v-model="form.dakhilaRef"/></label><label>Dakhila status<select v-model="form.dakhilaStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.dakhila_status" :key="v" :value="v">{{v}}</option></select></label></div></section>
<section class="land-form-section"><h3>03 · Ownership and Succession</h3><div class="form-grid"><label>Ownership status<select v-model="form.ownershipStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.ownership_status" :key="v" :value="v">{{v}}</option></select></label><label>Death indicator<select v-model="form.deathIndicator"><option value="">Select</option><option v-for="v in VALUE_SETS.death_indicator" :key="v" :value="v">{{v}}</option></select></label><label>Successor process<select v-model="form.successorProcess"><option value="">Select</option><option v-for="v in VALUE_SETS.successor_process" :key="v" :value="v">{{v}}</option></select></label><label>Mutation after succession<select v-model="form.mutationAfterSuccession"><option value="">Select</option><option v-for="v in VALUE_SETS.mutation_after_succession" :key="v" :value="v">{{v}}</option></select></label><label>Succession status<select v-model="form.successionStatus"><option value="">Select</option><option v-for="v in VALUE_SETS.succession_status" :key="v" :value="v">{{v}}</option></select></label></div><div class="land-subheading"><b>Recorded owners</b><IconButton icon="add" label="Add owner" @click="form.owners.push({email:'',ownerRef:'',sharePercent:null,isDeceased:false})"/></div><div v-for="(owner,i) in form.owners" :key="i" class="owner-row"><input v-model="owner.email" type="email" placeholder="Owner email"/><input v-model="owner.ownerRef" placeholder="Owner reference"/><input v-model.number="owner.sharePercent" type="number" min="0" max="100" step="0.01" placeholder="Share %"/><label class="check-line"><input v-model="owner.isDeceased" type="checkbox"/> Deceased</label><IconButton icon="delete" label="Remove owner" variant="danger" @click="form.owners.splice(i,1)"/></div></section>
<section class="land-form-section"><h3>04 · Case and Mortgage</h3><div class="form-grid"><label class="check-line"><input v-model="form.caseExists" type="checkbox"/> Case exists</label><label>Case reference<input v-model="form.caseRef"/></label><label>Case type<select v-model="form.caseType"><option value="">Select type</option><option v-for="v in VALUE_SETS.case_type" :key="v" :value="v">{{v}}</option></select></label><label>Case status<select v-model="form.caseStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.case_status" :key="v" :value="v">{{v}}</option></select></label><label class="check-line"><input v-model="form.mortgageExists" type="checkbox"/> Mortgage exists</label><label>Mortgage reference<input v-model="form.mortgageRef"/></label><label>Mortgage status<select v-model="form.mortgageStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.mortgage_status" :key="v" :value="v">{{v}}</option></select></label></div></section>
<section class="land-form-section"><h3>05 · Price</h3><div class="form-grid"><label>Last sold price (BDT)<input v-model.number="form.lastSoldPriceBdt" type="number" min="0" step="1"/></label><label>Last sold date<input v-model="form.lastSoldDate" type="date"/></label><label>Last sold deed reference<input v-model="form.lastSoldDeedRef"/></label><label>Reserved price (BDT)<input v-model.number="form.reservedPriceBdt" type="number" min="0" step="1"/></label><label>Reserved price date<input v-model="form.reservedPriceDate" type="date"/></label><label>Price flag<select v-model="form.priceFlag"><option value="">Select flag</option><option v-for="v in VALUE_SETS.price_flag" :key="v" :value="v">{{v}}</option></select></label></div></section>
<section class="land-form-section"><h3>06 · Verification snapshot</h3><p class="muted">Values are entered by the officer; they are not automatically calculated.</p><div class="form-grid"><label>Overall status<select v-model="form.overallStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.overall_status" :key="v" :value="v">{{v}}</option></select></label><label>Risk level<select v-model="form.riskLevel"><option value="">Select risk</option><option v-for="v in VALUE_SETS.risk_level" :key="v" :value="v">{{v}}</option></select></label><label>Document-level status<select v-model="form.documentLevelStatus"><option value="">Select status</option><option v-for="v in VALUE_SETS.document_level_status" :key="v" :value="v">{{v}}</option></select></label><label>Ownership check<select v-model="form.ownershipCheck"><option value="">Select</option><option v-for="v in VALUE_SETS.ownership_check" :key="v" :value="v">{{v}}</option></select></label><label>Succession check<select v-model="form.successionCheck"><option value="">Select</option><option v-for="v in VALUE_SETS.succession_check" :key="v" :value="v">{{v}}</option></select></label><label>Case check<select v-model="form.caseCheck"><option value="">Select</option><option v-for="v in VALUE_SETS.case_check" :key="v" :value="v">{{v}}</option></select></label><label>Mortgage check<select v-model="form.mortgageCheck"><option value="">Select</option><option v-for="v in VALUE_SETS.mortgage_check" :key="v" :value="v">{{v}}</option></select></label><label>Price check<select v-model="form.priceCheck"><option value="">Select</option><option v-for="v in VALUE_SETS.price_check" :key="v" :value="v">{{v}}</option></select></label><label>Verified at<input v-model="form.verifiedAt" type="datetime-local"/></label><label>Verification version<input v-model="form.verificationVersion"/></label><label>Source snapshot version<input v-model="form.sourceSnapshotVersion"/></label><label class="span-all">Verification flags<select v-model="form.verificationFlags"><option value="">None</option><option v-for="v in VALUE_SETS.verification_flags" :key="v" :value="v">{{v}}</option></select></label></div></section>
<section class="land-form-section"><div class="land-subheading"><h3>07 · Transactions</h3><IconButton icon="add" label="Add transaction" @click="form.transactions.push({transactionId:'',transactionType:'',date:'',amountBdt:null,deedRef:'',sellerRef:'',buyerRef:'',status:''})"/></div><div v-for="(tx,i) in form.transactions" :key="tx.id||i" class="transaction-editor"><div class="form-grid"><label>Transaction ID<input v-model="tx.transactionId" placeholder="Generated if blank"/></label><label>Transaction type<select v-model="tx.transactionType"><option value="">Select type</option><option v-for="v in VALUE_SETS.transaction_type" :key="v" :value="v">{{v}}</option></select></label><label>Date<input v-model="tx.date" type="date"/></label><label>Amount (BDT)<input v-model.number="tx.amountBdt" type="number" min="0"/></label><label>Deed reference<input v-model="tx.deedRef"/></label><label>Seller reference<input v-model="tx.sellerRef"/></label><label>Buyer reference<input v-model="tx.buyerRef"/></label><label>Status<select v-model="tx.status"><option value="">Select status</option><option v-for="v in VALUE_SETS.transaction_status" :key="v" :value="v">{{v}}</option></select></label></div><div class="transaction-remove"><IconButton icon="delete" label="Remove transaction" variant="danger" @click="form.transactions.splice(i,1)"/></div></div><p v-if="!form.transactions.length" class="muted">No transaction rows. Add rows only when transfer history exists.</p></section>
<div class="form-footer"><IconButton icon="save" label="Save draft" @click.prevent="saveDraft" :loading="saving"/><IconButton icon="publish" label="Send to final record" type="submit" :loading="publishing"/><IconButton icon="cancel" label="Cancel" @click="$router.back()"/></div><p v-if="error" class="inline-alert">{{error}}</p></form><ConfirmDialog :open="discardOpen" title="Discard draft" message="Delete this draft? The final land record will remain unchanged." confirm-label="Discard draft" danger @cancel="discardOpen=false" @confirm="discardDraft"/></div></template>
<script setup lang="ts">import{computed,onMounted,ref}from'vue';import{useRoute,useRouter}from'vue-router';import api from'@/services/api';import IconButton from'@/components/ui/IconButton.vue';import ConfirmDialog from'@/components/ui/ConfirmDialog.vue';import{VALUE_SETS}from'@/constants/valueSets';import{notify}from'@/composables/useNotify';
const route=useRoute(),router=useRouter(),isCreate=computed(()=>route.params.kind==='creates'),draftId=computed(()=>String(route.params.id||'')),isNew=computed(()=>draftId.value==='new'),saving=ref(false),publishing=ref(false),error=ref(''),hasDraft=ref(false),isStale=ref(false),discardOpen=ref(false);const blank=()=>({recordType:'RS',dagNo:'',jlNo:'',khatianNo:'',areaDecimal:null as number|null,landClass:'',khatianRef:'',khatianStatus:'',deedNo:'',deedDate:'',deedRegistrationOffice:'',mutationRef:'',mutationStatus:'',dcrRef:'',dcrStatus:'',dakhilaRef:'',dakhilaStatus:'',ownershipStatus:'',deathIndicator:'',successorProcess:'',mutationAfterSuccession:'',successionStatus:'',caseExists:false,caseRef:'',caseType:'',caseStatus:'',mortgageExists:false,mortgageRef:'',mortgageStatus:'',lastSoldPriceBdt:null as number|null,lastSoldDate:'',lastSoldDeedRef:'',reservedPriceBdt:null as number|null,reservedPriceDate:'',priceFlag:'',overallStatus:'',riskLevel:'',verificationFlags:'',documentLevelStatus:'',ownershipCheck:'',successionCheck:'',caseCheck:'',mortgageCheck:'',priceCheck:'',verifiedAt:'',verificationVersion:'',sourceSnapshotVersion:'',owners:[] as any[],transactions:[] as any[]});const form=ref<any>(blank());const path=computed(()=>`/officer/drafts/${isCreate.value?'creates':'updates'}`);
function normalizePayload(data:any){const source=data.payload||data;const {area,areaId,landId,createdAt,updatedAt,createdBy,updatedBy,hasUpdateDraft,...fields}=source;return {...blank(),...fields,owners:(source.owners||[]).map((o:any)=>({...o,email:o.email||o.ownerEmail})),transactions:(source.transactions||[]).map((tx:any)=>({...tx,transactionId:tx.transactionId||''}))}}
onMounted(async()=>{if(isNew.value)return;try{const{data}=await api.get(`${path.value}/${draftId.value}`);form.value=normalizePayload(data);hasDraft.value=true;isStale.value=!!data.isStale}catch(e:any){if(!isCreate.value){try{const{data}=await api.get(`/officer/lands/${draftId.value}`);form.value=normalizePayload(data)}catch(err:any){error.value=err.response?.data?.detail||'Could not load land record'}}else error.value=e.response?.data?.detail||'Could not load draft'}});
async function saveDraft(){saving.value=true;error.value='';try{if(isCreate.value){if(isNew.value){const{data}=await api.post(path.value,form.value);hasDraft.value=true;await router.replace(`${path.value}/${data.id}`)}else await api.put(`${path.value}/${draftId.value}`,form.value)}else await api.put(`${path.value}/${draftId.value}`,form.value);hasDraft.value=true;notify('Draft saved','success')}catch(e:any){error.value=e.response?.data?.detail||'Could not save draft'}finally{saving.value=false}}
async function publish(){publishing.value=true;error.value='';try{if(isCreate.value){if(isNew.value){const{data}=await api.post(path.value,form.value);await api.post(`${path.value}/${data.id}/publish`,{})}else{await api.put(`${path.value}/${draftId.value}`,form.value);await api.post(`${path.value}/${draftId.value}/publish`,{})}}else{if(hasDraft.value){await api.put(`${path.value}/${draftId.value}`,form.value);await api.post(`${path.value}/${draftId.value}/publish`,{})}else await api.put(`/officer/lands/${draftId.value}`,form.value)}await router.push('/dashboard/landofficer/lands')}catch(e:any){error.value=e.response?.data?.detail||'Could not publish land record'}finally{publishing.value=false}}
async function discardDraft(){try{await api.delete(`${path.value}/${draftId.value}`);discardOpen.value=false;hasDraft.value=false;isStale.value=false;if(!isCreate.value){const{data}=await api.get(`/officer/lands/${draftId.value}`);form.value=normalizePayload(data)}else await router.push('/dashboard/landofficer/drafts/creates')}catch(e:any){error.value=e.response?.data?.detail||'Could not discard draft'}}
</script>
